"""Prepared discovery journey. Browser-local interaction; no API or lead transmission."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def payload():
    pack = json.loads((ROOT / 'data/technology-discovery-enriched.json').read_text(encoding='utf-8'))
    demo = json.loads((ROOT / 'data/discovery-demo-values.json').read_text(encoding='utf-8'))
    companies = []
    for c in pack['companies']:
        m = c['metrics']; overrides = demo['values'][c['company_number']]
        turnover = overrides.get('turnover_gbp', m['turnover_gbp']['value'])
        companies.append({
            'id': c['company_number'], 'name': c['name'], 'website': c['website_returned'],
            'locality': c['registered_location']['locality'],
            'region': c['registered_location']['region'] or c['registered_location']['country'],
            'lat': c['registered_location']['latitude'], 'lon': c['registered_location']['longitude'],
            'incorporated': c['legal_identity']['incorporated_on'], 'status': c['legal_identity']['status'],
            'employees': m['average_employees']['value'], 'turnover': turnover,
            'funding': overrides['funding_gbp'], 'netAssets': m['net_assets_gbp']['value'],
            'accountsEnd': c['latest_accounts']['period_end'], 'summary': c['business_description']['summary'],
            'capabilities': c['business_description']['capabilities'], 'products': c['product_examples'],
            'sic': c['reported_sic_codes'], 'notes': c['caveats'],
            'identityNote': c['business_description']['website_identity_note'],
            'sources': [pack['sources']['ch-' + c['company_number']], pack['sources'][c['latest_accounts']['source_id']], pack['sources']['website-' + c['company_number']]],
            'metricProvenance': {'turnover': 'illustrative' if 'turnover_gbp' in overrides else 'filed', 'funding': 'illustrative'},
        })
    return {'companies': companies, 'map': json.loads((ROOT / 'data/uk-map.json').read_text()),
            'classifications': {k: pack['cached_api']['response'][k] for k in ['RTICs', 'RSICs', 'RNAICs']},
            'researchDate': pack['researched_on'], 'apiAttempt': 2,
            'mode': 'prepared-demonstration', 'externalRequests': False}

